from pathlib import Path
p=Path('strategy.html'); s=p.read_text(); base=s[s.index('<script>')+8:s.index('let a,run=false;')]; ui=s[s.index('let a,run=false;'):s.index('</script></html>')];
# stationary initial deployment and formation command targets via existing PIBT
ui=ui.replace('let start=null;','let start=null, cursor=null, formation="block", groups=new Map();')
ui=ui.replace("g.clearRect(0,0,1200,800);", "g.fillStyle='#263e36';g.fillRect(0,0,1200,800);g.strokeStyle='#ffffff09';for(let i=0;i<1200;i+=40){g.beginPath();g.moveTo(i,0);g.lineTo(i,800);g.stroke()}for(let i=0;i<800;i+=40){g.beginPath();g.moveTo(0,i);g.lineTo(1200,i);g.stroke()}")
ui=ui.replace("if(b.hp<=0)continue;","if(b.hp<=0||b.side&&!visibleAt(b.x,b.y))continue;")
ui=ui.replace("$('economy').textContent=", "fog();mini();if(start&&cursor){g.strokeStyle='#b9f8d4';g.strokeRect(start[0],start[1],cursor[0]-start[0],cursor[1]-start[1])} $('economy').textContent=")
ui=ui.replace("a=new Strategy();run=true;draw()", "a=new Strategy();groups.clear();run=false;draw()")
ui=ui.replace("if(e.button===0)start=point(e)","if(e.button===0){start=point(e);cursor=start;c.setPointerCapture(e.pointerId)}")
ui=ui.replace("a.pending={ids:new Set(a.selected),x,y};return", "a.pending={ids:new Set(a.selected),x,y,formation};return")
ui=ui.replace("c.oncontextmenu=e=>{e.preventDefault();a.selected.clear();draw()}","c.onpointermove=e=>{if(start){cursor=point(e);draw()}};c.onpointercancel=()=>{start=null};c.oncontextmenu=e=>{e.preventDefault();let [x,y]=point(e);if(a.selected.size)a.pending={ids:new Set(a.selected),x,y,formation};draw()}")
ui=ui.replace("function btn(label,fn)","function btn(label,fn,parent=orders)").replace('orders.append(b)','parent.append(b)')
ui=ui.replace("()=>a.train(0,k));reset();loop();", "()=>a.train(0,k),$('troops'));reset();loop();")
# formation target mapping in original shared planner
base=base.replace('let {ids,x,y}=this.pending;', 'let {ids,x,y,formation}=this.pending;').replace('for(const u of chosen){let best=-1,score=Infinity;', 'for(const [index,u] of chosen.entries()){let tx=x,ty=y;if(formation===\'line\'){ty+=(index-(chosen.length-1)/2)*10}else if(formation===\'column\'){tx+=(index-(chosen.length-1)/2)*10}let best=-1,score=Infinity;').replace('(p%120*10+5-x)**2+((p/120|0)*10+5-y)**2','(p%120*10+5-tx)**2+((p/120|0)*10+5-ty)**2')
extra='''function visibleAt(x,y){return a.units.some(u=>!u.dead&&!u.side&&Math.hypot(u.x-x,u.y-y)<(u.kind===11?300:u.kind===6?230:150))||a.buildings.some(b=>!b.side&&b.hp>0&&Math.hypot(b.x-x,b.y-y)<120)}
const mask=document.createElement('canvas');mask.width=1200;mask.height=800;const mg=mask.getContext('2d');function fog(){mg.globalCompositeOperation='source-over';mg.clearRect(0,0,1200,800);mg.fillStyle='rgba(7,15,17,.72)';mg.fillRect(0,0,1200,800);mg.globalCompositeOperation='destination-out';for(const u of [...a.units.filter(u=>!u.dead&&!u.side),...a.buildings.filter(b=>!b.side&&b.hp>0)]){mg.beginPath();mg.arc(u.x,u.y,u.kind===11?300:u.kind===6?230:u.kind===undefined?120:150,0,Math.PI*2);mg.fill()}g.drawImage(mask,0,0)}
function mini(){const m=$('mini').getContext('2d');m.fillStyle='#132720';m.fillRect(0,0,240,160);m.fillStyle='#65766b';for(const o of a.obstacles)m.fillRect(o.x/5,o.y/5,o.w/5,o.h/5);for(const u of [...a.units,...a.buildings]){if(u.dead||u.hp<=0||u.side&&!visibleAt(u.x,u.y))continue;m.fillStyle=colors[u.side];m.fillRect(u.x/5,u.y/5,u.type?5:2,u.type?5:2)}}
$('formation').onchange=e=>formation=e.target.value;document.addEventListener('keydown',e=>{if(e.target.tagName==='SELECT')return;if(e.code==='Space'){e.preventDefault();run=!run}if(/^Digit[1-9]$/.test(e.code)){let k=e.code.slice(-1);if(e.ctrlKey){e.preventDefault();groups.set(k,new Set(a.selected))}else if(groups.has(k))a.selected=new Set(a.units.filter(u=>!u.dead&&groups.get(k).has(u.id)).map(u=>u.id))}if(e.key==='Escape')a.selected.clear();draw()});
'''
# extra must initialize before reset
ui=ui.replace('reset();loop();',extra+'reset();loop();')
header='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>钢铁战线 V2.0</title><style>*{box-sizing:border-box}body{margin:0;background:#101a1c;color:#e5eee5;font:14px system-ui}header{padding:16px 22px;border-bottom:1px solid #35453f;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}h1{margin:0;font-size:23px}small{color:#9eafa4}main{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:12px;padding:14px}section,aside{background:#192824;border:1px solid #35483e;padding:12px;border-radius:8px}canvas{width:100%;display:block;touch-action:none}#c{background:#263e36}button,select{background:#293c34;color:#e5eee5;border:1px solid #49604e;border-radius:5px;padding:8px;margin:3px;cursor:pointer}button:hover{background:#46664d}#orders,#troops{display:grid;grid-template-columns:1fr 1fr}#notice{grid-column:span 2;color:#b4c9a9}h3{font-size:13px;color:#a8c4af;margin:12px 0 6px}pre{font-size:12px;white-space:pre-wrap}p{color:#a8baa9;font-size:12px}#mini{max-width:240px}@media(max-width:800px){main{grid-template-columns:1fr}}</style><header><div><small>STEEL FRONT / COMMAND</small><h1>钢铁战线 V2.0</h1></div><div id="economy"></div><div><button id="reset">新战局</button><button id="play">开始 / 暂停</button><button id="step">单步</button></div></header><main><section><canvas id="c" width="1200" height="800"></canvas><p>框选友军；右键或选中后点击下达移动指令。Ctrl+1–9 保存编队，数字键召回，空格暂停。</p><label>阵型 <select id="formation"><option value="block">方阵</option><option value="line">纵向战列</option><option value="column">横向行列</option></select></label></section><aside><h3>战场态势</h3><canvas id="mini" width="240" height="160"></canvas><pre id="stats"></pre><h3>基地建设 / 科技</h3><div id="orders"></div><h3>兵种生产</h3><div id="troops"></div></aside></main>'''
Path('index.html').write_text(header+'<script>'+base+ui+'</script></html>')
